  'chat.brandBrowserAssistReadFailed': 'לא ניתן היה לקרוא את דף הדפדפן. ודא שאתר המותג פתוח ועמוס במלואו.',
  'chat.brandBrowserAssistMessage': 'Open Design זקוק לסיוע בדפדפן כדי לסיים את מיצוי המותג הזה. השתמש בכרטיס שלמטה כדי לפתוח את הדפדפן, ולאחר מכן לחץ על עוד, בחר דף הורד, המתן להודעת ההצלחה והשתמש בכרטיס ה- Next Step השמאלי כדי להמשיך בחילוץ. אם הכרטיס אינו גלוי, פתח ידנית את לשונית הדפדפן בצד ימין ופעל על עוד > דף הורדה > המשך חילוץ.',
