  'chat.brandBrowserAssistDownloadGuideTitle': 'הדפדפן נפתח',
  'chat.brandBrowserAssistDownloadGuideDetails': 'שלב 1: פתח או עבור ללשונית דפדפן בצד ימין ונקה כל בדיקה אנושית. שלב 2: לחץ על עוד ולאחר מכן על הורד דף. שלב 3: המתן להודעת ההצלחה של תמונת המצב השמורה. שלב 4: חזור לכרטיס השלב השמאלי ולחץ על המשך חילוץ כדי להמשיך בחילוץ הפרוגרמטי.',
