  'chat.example1Prompt': 'צור סיפון רוד-שואו למשקיעים של 10 שקופיות עבור סטודיו לעיצוב בשלבי הזרע. כלול כיסוי, בעיה, תובנה, מוצר, שוק, משיכה, מודל עסקי, צוות, שאל וצור קשר. ליטוש עריכה, תרשימים חדים, נרטיב חזק ומספיק איפוק לפגישת משקיעים.',
  'chat.example2Title': 'דף נחיתה של אפליקציית Notes',
  'chat.example2Tag': 'נחיתה',
  'chat.example2Prompt': 'עצב דף נחיתה עבור אפליקציית AI Notes אשר לוכדת פגישות, מחפשת נקודות עיקריות והופכת הערות למשימות. כלול גיבור, תצוגה מקדימה של המוצר, סיפור תכונה, הוכחה חברתית, תמחור, שאלות נפוצות ו-CTA. אסתטיקת פרודוקטיביות רגועה עם נתיב המרה ברור.',
  'chat.example3Title': 'אב טיפוס נייד למדיטציה',
  'chat.example3Tag': 'נייד',
  'chat.example3Prompt': 'אב טיפוס של ארבעה מסכים ניידים לאפליקציית מדיטציה: בית, נגן הפעלה, התקדמות ופסים, ואיסוף שינה. כלול מצבי כניסה, ניווט תחתון, פקדים נגישים והערות תנועה עדינה כדי שהזרימה תרגיש מוכן לבדיקה.',

