  'designFiles.documentTemplate.scenario.document': 'עבור מסמכים, הגדר קהל, טון, מבנה מקטע, חומר מקור, ציטוטים או נתונים, ציפיות פריסה ודרישות PDF/יצוא.',
  'designFiles.documentTemplate.scenario.image': 'עבור תמונות, ציין נושא, יחס רוחב-גובה, קומפוזיציה, סגנון חזותי, אסימוני מותג, קובצי עזר ואילוצים שליליים.',
  'designFiles.documentTemplate.scenario.video': 'עבור וידאו, נסח לוח תכנון עם סצנות, תזמון, כתוביות, תנועה, נכסים, הערות אודיו ופורמט פלט.',
  'designFiles.documentTemplate.scenario.hyperframes': 'עבור HyperFrames, תאר את קטע התנועה ב-HTML: סצנות, ציר זמן, כיתובים, רגעי תגובתיות אודיו, מעברים ודרישות לכידה/ייצוא.',
  'designFiles.documentTemplate.scenario.audio': 'לשמע, הגדירו כיוון קול או מוזיקה, משך, מצב רוח, תסריט או העתקה, קצב, הערות הגייה ושימוש סופי.',
  'designFiles.documentTemplate.scenario.liveArtifact': 'עבור חפצים חיים, תאר מקורות נתונים, קצב רענון, ווידג\'טים, מסננים, אינטראקציות, מצבי ריקים/טעינה/שגיאה וכל התראות או אוטומציות.',
  'designFiles.documentTemplate.scenario.designSystem': 'עבור מערכות עיצוב, רשום יעדי מותג, אסימונים, טיפוגרפיה, צבע, מרווח, רכיבים, נכסים, הפניות וכללים שיש לעקוב אחריהם או להימנע מהם.',
  'designFiles.documentTemplate.scenario.default': 'תאר את הקהל, התוכנה, התוכן הנדרש, הפניות, אילוצים ואיך שנעשה צריך להיראות.',
