  'nextStep.planGenerateTitle': 'יצירת תוצר',
  'nextStep.planGenerateBody': 'השתמש בתוכנית Markdown המאושרת כמקור האמת להרצת העיצוב הבאה.',
  'nextStep.planImproveTitle': 'שפר את המסמך',
  'nextStep.planImproveBody': 'שפרו את מסמך התוכנית הנוכחי לפני יצירת התוצר הסופי.',
  'nextStep.planGeneratePrompt': 'השתמשו ב-\'{file}\' כמקור האמת. קראו תחילה את המסמך, שמרו על ההחלטות שבו, ולאחר מכן צרו את תוצר העיצוב הסופי התואם לו. אם הוא מתאר שקף, צרו מצגת; אם מדובר בתוכנית PRD או באב טיפוס, הפיקו את אב הטיפוס או את ה-wireframes; אם זה לוח תכנון או בריף יצירתי, צרו את תוצר המדיה או העיצוב המתאים. לפני היצירה, קראו כל משימה חוסמת או סתירה שאינכם יכולים לפתור.',
  'nextStep.planImprovePrompt': 'קראו את `{file}` ושפרו אותו כמסמך תוכנית הניתן לעריכה. צמצמו את ההיקף, מלאו חלקים חלשים, הוסיפו בדיקות קבלה חסרות ושמרו על TODO ושאלות פתוחות במקום שבו עדיין נדרש קלט מהמשתמש. אל תיצרו עדיין את תוצר העיצוב הסופי.',
  'nextStep.planImproveArtifactTitle': 'שיפור תוצר',
  'nextStep.planImproveArtifactBody': 'המשיכו לשפר את התוצר שנוצר במקום לחזור לתכנון.',
  'nextStep.planImproveArtifactPrompt': 'שפרו את \'{artifact}\' במקום. שמרו על תוצר העבודה הקיים ושפרו את המוצר, החזותיות, האינטראקציה והתוכן במידת ההשפעה המרבית. שמרו על התנהגות שכבר פועלת, ולאחר מכן סכמו את הקבצים שהשתנו ואת הסיכונים שנותרו.',
  'nextStep.planMergeTitle': 'יישור מסמך ותוצר',
  'nextStep.planMergeBody': 'התאימו בין התוכנית לתוצר שנוצר כדי שיתקדמו יחד.',
  'nextStep.planMergePrompt': 'קראו את `{document}` ואת `{artifact}` יחד. התייחסו למסמך כהנחיה ולתוצר כמימוש הנוכחי. התאימו ביניהם: עדכנו את התוצר כך שיתאים להחלטות שאושרו, עדכנו את המסמך רק במקומות שבהם הוא מיושן, ושמרו על TODO ושאלות פתוחות מפורשות לכל דבר שעדיין לא נפתר. שמרו על התנהגות קיימת שפועלת וסכמו מה השתנה בשני הקבצים.',

